CREATE TABLE IF NOT EXISTS exposed.funders (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    funder_name TEXT NOT NULL UNIQUE,
    funder_kind TEXT,
    company_number TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
